 private void chooseLocal(){act(()->{if(google!=null)google.cancel();controller.selectLocal();});}
 private void choose(AccountDirectory.Entry entry){a.dialog().setTitle(a.t("Open this ledger?","ഈ കണക്കുപുസ്തകം തുറക്കണോ?")) .setMessage(entry.email+"\n\n"+a.t("Your current records stay in their own ledger. Nothing is copied between accounts. Reconnect this account to sync its offline changes.","ഇപ്പോഴുള്ള കണക്കുകൾ അതത് കണക്കുപുസ്തകത്തിൽ തുടരും. അക്കൗണ്ടുകൾക്കിടയിൽ ഒന്നും പകർത്തില്ല. സമന്വയത്തിന് ഈ അക്കൗണ്ട് വീണ്ടും ബന്ധിപ്പിക്കുക.")) .setNegativeButton(a.t("Cancel","വേണ്ട"),null).setPositiveButton(a.t("Open ledger","തുറക്കുക"),(d,n)->act(()->{if(google!=null)google.cancel();controller.selectKnown(entry.subject);})).show();}
 private void connect(String reconnect){act(()->{if(google!=null)google.close();google=new GoogleConnection(a,new GoogleConnection.Listener(){public void connected(VerifiedDriveAccess access){act(()->{if(reconnect!=null){controller.reconnected(reconnect,access);controller.sync();}else{controller.verified(access);offerConnected(access.subject,access.email);}});}public void stopped(String message){a.toast(message);}});google.start(reconnect);});}
 private void offerConnected(String subject,String email){a.dialog().setTitle(a.t("Google account verified","Google അക്കൗണ്ട് പരിശോധിച്ചു")) .setMessage(email+"\n\n"+a.t("Use this account's separate Drive ledger? Only this ledger will sync. Your local-only records stay separate unless you choose to copy them later.","ഈ അക്കൗണ്ടിന്റെ വേറിട്ട Drive കണക്കുപുസ്തകം ഉപയോഗിക്കണോ? ഇത് മാത്രം സമന്വയിപ്പിക്കും. നിങ്ങൾ പ്രത്യേകം പകർത്താതെ ഫോണിലെ കണക്കുകൾ വേറിട്ടു തുടരും.")) .setNegativeButton(a.t("Not now","ഇപ്പോഴല്ല"),null).setPositiveButton(a.t("Use this Drive ledger","ഈ Drive കണക്കുകൾ ഉപയോഗിക്കുക"),(d,n)->act(()->{controller.selectKnown(subject);controller.sync();})).show();}
 private void confirmCopy(String subject,String email){a.dialog().setTitle(a.t("Copy local-only records?","ഫോണിലെ കണക്കുകൾ പകർത്തണോ?")) .setMessage(a.t("From: local-only ledger\nTo: ","മൂലം: ഫോണിലെ കണക്കുപുസ്തകം\nലക്ഷ്യം: ")+email+"\n\n"+a.t("Copies entries, people, categories, accounts, budgets, goals and preferences only if the destination has no local or Drive sync history. The original stays on this device. This choice can upload those copied records on sync.","ലക്ഷ്യത്തിൽ കണക്കുകളോ Drive ചരിത്രമോ ഇല്ലെങ്കിൽ മാത്രം കണക്കുകളും ആളുകളും വിഭാഗങ്ങളും അക്കൗണ്ടുകളും ബജറ്റും ലക്ഷ്യങ്ങളും ക്രമീകരണങ്ങളും പകർത്തും. മൂലപകർപ്പ് ഫോണിൽ തുടരും. പകർത്തിയ കണക്കുകൾ സമന്വയത്തിൽ ക്ലൗഡിലേക്ക് അയയ്ക്കാം.")) .setNegativeButton(a.t("Cancel","വേണ്ട"),null).setPositiveButton(a.t("Copy into this account","ഈ അക്കൗണ്ടിലേക്ക് പകർത്തുക"),(d,n)->act(()->controller.copyLocal(subject))).show();}
 void confirmCloudReset(){LedgerController.Status s=controller.status();if(s.subject==null)return;a.dialog().setTitle(a.t("Reset this Google ledger?","ഈ Google കണക്കുകൾ നീക്കണോ?")) .setMessage(s.email+"\n\n"+a.t("Deletes entries, budgets, goals, custom items and preferences in this account. Other devices must discard their old ledger when they reconnect. This is permanent. Your separate local-only ledger and saved backup/CSV files stay untouched. Small content-free reset and deletion markers remain in Drive to stop old offline copies from restoring deleted records. Editing pauses until reset completes.","ഈ അക്കൗണ്ടിലെ കണക്കുകളും ബജറ്റും ലക്ഷ്യങ്ങളും സ്വന്തം ഇനങ്ങളും ക്രമീകരണങ്ങളും നീക്കും. മറ്റു ഉപകരണങ്ങൾ വീണ്ടും ബന്ധിപ്പിക്കുമ്പോൾ പഴയ കണക്കുകൾ ഉപേക്ഷിക്കണം. തിരിച്ചെടുക്കാനാവില്ല. ഫോണിലെ വേറിട്ട കണക്കുകളും ബാക്കപ്പും CSVയും മാറില്ല. പഴയ പകർപ്പുകൾ നീക്കിയ കണക്കുകൾ തിരികെ കൊണ്ടുവരാതിരിക്കാൻ വിവരങ്ങളില്ലാത്ത ചെറിയ അടയാളങ്ങൾ Drive-ൽ തുടരും. നീക്കൽ പൂർത്തിയാകുന്നതുവരെ മാറ്റങ്ങൾ നിർത്തും.")) .setNegativeButton(a.t("Cancel","വേണ്ട"),null).setPositiveButton(a.t("Reset this account","ഈ അക്കൗണ്ട് നീക്കുക"),(d,n)->act(()->{controller.beginReset(s.subject);controller.resumeReset();})).show();}
 private void reviewReset(String subject,String email){if(!controller.resetObserved()){act(()->controller.sync());return;}a.dialog().setTitle(a.t("Cloud ledger was reset","ക്ലൗഡ് കണക്കുകൾ നീക്കിയിട്ടുണ്ട്")) .setMessage(email+"\n\n"+a.t("Another device reset this account. To reconnect, discard this device's old account records and pending changes. They will not be uploaded. Save an encrypted backup first if you need a copy. Your separate local-only ledger is unchanged.","മറ്റൊരു ഉപകരണത്തിൽ ഈ അക്കൗണ്ട് നീക്കിയിട്ടുണ്ട്. വീണ്ടും ബന്ധിപ്പിക്കാൻ ഈ ഉപകരണത്തിലെ പഴയ അക്കൗണ്ട് കണക്കുകളും ബാക്കിയുള്ള മാറ്റങ്ങളും ഉപേക്ഷിക്കണം. അവ അയയ്ക്കില്ല. പകർപ്പ് വേണമെങ്കിൽ ആദ്യം എൻക്രിപ്റ്റ് ചെയ്ത ബാക്കപ്പ് സൂക്ഷിക്കുക. വേറിട്ട ഫോണിലെ കണക്കുപുസ്തകം മാറില്ല.")) .setNegativeButton(a.t("Keep offline for now","ഇപ്പോൾ ഫോണിൽ സൂക്ഷിക്കുക"),null).setPositiveButton(a.t("Discard old account records","പഴയ അക്കൗണ്ട് കണക്കുകൾ ഉപേക്ഷിക്കുക"),(d,n)->act(()->{controller.acceptObservedReset(subject);controller.sync();})).show();}
 void confirmDisconnect(String subject,String email){a.dialog().setTitle(a.t("Disconnect Google access?","Google അനുമതി പിൻവലിക്കണോ?")) .setMessage(email+"\n\n"+a.t("Stops sync and asks Google to revoke all permissions previously granted to Hisab for this account. On success, the account is forgotten here and you return to the local-only ledger. Your Drive ledger and separate offline cache are not erased. Saved backups and CSV files are unchanged. To delete cloud records, reset this cloud ledger before disconnecting. If Google cannot confirm revocation, sync stays paused and you can retry.","സമന്വയം നിർത്തി ഈ അക്കൗണ്ടിൽ Hisab-ന് നൽകിയ എല്ലാ അനുമതികളും പിൻവലിക്കാൻ Google-നോട് ആവശ്യപ്പെടും. വിജയിച്ചാൽ അക്കൗണ്ട് ഇവിടെ മറന്ന് ഫോണിലെ വേറിട്ട കണക്കുപുസ്തകത്തിലേക്ക് മടങ്ങും. Drive കണക്കുകളും ഫോണിലെ വേറിട്ട പകർപ്പും നീക്കില്ല. ബാക്കപ്പും CSVയും മാറില്ല. ക്ലൗഡ് കണക്കുകൾ നീക്കണമെങ്കിൽ ബന്ധം നീക്കുന്നതിന് മുമ്പ് ആ കണക്കുപുസ്തകം നീക്കുക. Google ഉറപ്പു നൽകാത്തപക്ഷം സമന്വയം നിർത്തിവെക്കും; വീണ്ടും ശ്രമിക്കാം.")) .setNegativeButton(a.t("Cancel","വേണ്ട"),null).setPositiveButton(a.t("Disconnect Google","Google ബന്ധം നീക്കുക"),(d,n)->act(()->{if(google!=null)google.cancel();controller.disconnect(subject);})).show();}
 private void forget(String subject,String email){a.dialog().setTitle(a.t("Forget this Google account?","ഈ Google അക്കൗണ്ട് മറക്കണോ?")) .setMessage(email+"\n\n"+a.t("Returns to your local-only ledger. Drive records and the separate cached account database are not deleted. This does not revoke Hisab's Google permission. You can reconnect the same account later.","ഫോണിലെ വേറിട്ട കണക്കുപുസ്തകത്തിലേക്ക് മടങ്ങും. Drive കണക്കുകളും അക്കൗണ്ടിന്റെ ഫോണിലെ പകർപ്പും നീക്കില്ല. Google-ൽ Hisab-ന് നൽകിയ അനുമതി പിൻവലിക്കില്ല. ഇതേ അക്കൗണ്ട് പിന്നീട് വീണ്ടും ബന്ധിപ്പിക്കാം.")) .setNegativeButton(a.t("Cancel","വേണ്ട"),null).setPositiveButton(a.t("Forget on this device","ഈ ഉപകരണത്തിൽ മറക്കുക"),(d,n)->act(()->{if(google!=null)google.cancel();controller.forget(subject);})).show();}
 private void reviewConflict(){act(()->{ConflictReviewStore.Review review=controller.conflict();if(review==null){RepaymentReviewStore.Review payments=controller.repaymentReview();if(payments!=null)reviewRepayments(payments);else controller.sync();return;}LinearLayout content=a.dialogBody();content.addView(a.text(a.t("Different devices changed the same record. Choose the version to keep. No amount is chosen for you. If several records conflict, choices apply only after every review and ledger check succeeds.","വ്യത്യസ്ത ഉപകരണങ്ങളിൽ ഒരേ കണക്ക് മാറ്റിയിട്ടുണ്ട്. സൂക്ഷിക്കേണ്ട പകർപ്പ് തിരഞ്ഞെടുക്കുക. തുക നിങ്ങൾക്കായി തിരഞ്ഞെടുക്കില്ല. ഒന്നിലധികം കണക്കുകൾക്ക് വ്യത്യാസമുണ്ടെങ്കിൽ എല്ലാ പരിശോധനയും കഴിഞ്ഞുമാത്രം മാറ്റം നടപ്പാക്കും."),14,a.MUTED,false));for(int i=0;i<review.conflict.versions.size();i++){final int choice=i;SyncModel.Record record=review.conflict.versions.get(i);a.gap(content,14);TextView version=a.text(a.t("Version ","പകർപ്പ് ")+(i+1),17,a.FG,true);content.addView(version);content.addView(a.text(describe(record,review),14,a.FG,false));a.gap(content,7);content.addView(a.button(a.t("Keep version ","പകർപ്പ് സൂക്ഷിക്കുക ")+(i+1),()->confirmVersion(review,choice),false));}ScrollView scroll=new ScrollView(a);scroll.addView(content);a.dialog().setTitle(a.t("Review changes","മാറ്റങ്ങൾ പരിശോധിക്കുക")).setView(scroll).setNegativeButton(a.t("Later","പിന്നീട്"),null).show();});}
 private String reference(String id,Map<String,List<SyncModel.Record>> candidates)throws Exception{if(id.isEmpty())return "";if(id.equals("Debt")||id.equals("Transfer"))return id;List<SyncModel.Record> records=candidates.get(id);if(records==null)return a.t("Unavailable reference ","ലഭ്യമല്ലാത്ത ബന്ധം ")+id;Set<String> names=new LinkedHashSet<>();for(SyncModel.Record record:records)if(!record.deleted){JSONObject j=new JSONObject(record.payload);if(j.has("name"))names.add(j.getString("name"));else if(j.optString("type").equals("transaction"))names.add(j.optString("kind")+" · "+j.optString("day")+" · "+Ledger.number(j.getLong("amount"))+" "+j.optString("currency","INR"));}return names.isEmpty()?a.t("Deleted reference","നീക്കിയ ബന്ധം"):String.join(" / ",names);}
 String describe(SyncModel.Record r,ConflictReviewStore.Review review)throws Exception{return describe(r,review.candidates);}
 private String human(String value){switch(value){case "transaction":return a.t("Entry","കണക്ക്");case "income":return a.t("Income","വരുമാനം");case "expense":return a.t("Expense","ചെലവ്");case "lent":return a.t("Money lent","കൊടുത്ത കടം");case "borrowed":return a.t("Money borrowed","വാങ്ങിയ കടം");case "repay_in":return a.t("Repayment received","തിരിച്ചുകിട്ടിയ തുക");case "repay_out":return a.t("Repayment paid","തിരിച്ചടച്ച തുക");case "transfer":return a.t("Transfer","കൈമാറ്റം");case "budget":return a.t("Budget","ബജറ്റ്");case "goal":return a.t("Goal","ലക്ഷ്യം");case "catalog":return a.t("Custom item","സ്വന്തം ഇനം");case "preferences":return a.t("Preferences","ക്രമീകരണങ്ങൾ");default:return value;}}
 private String describe(SyncModel.Record r,Map<String,List<SyncModel.Record>> candidates)throws Exception{JSONObject j=new JSONObject(r.payload);StringBuilder out=new StringBuilder();String[][] fields={{"type","Record","കണക്ക്"},{"kind","Entry type","ഇനം"},{"day","Date","തീയതി"},{"name","Name","പേര്"},{"note","Note","കുറിപ്പ്"},{"entityType","Item type","ഇനം"},{"color","Colour","നിറം"},{"icon","Icon number","ഐക്കൺ നമ്പർ"}};for(String[] field:fields)if(j.has(field[0]))out.append(a.t(field[1],field[2])).append(": ").append(field[0].equals("type")||field[0].equals("kind")?human(j.getString(field[0])):j.get(field[0])).append('\n');for(String key:new String[]{"amount","target","saved"})if(j.has(key))out.append(key.equals("amount")?a.t("Amount","തുക"):key.equals("target")?a.t("Target","ലക്ഷ്യം"):a.t("Saved","സൂക്ഷിച്ചത്")).append(": ").append(Ledger.number(j.getLong(key))).append(' ').append(j.optString("currency","INR")).append('\n');if(j.has("values")){JSONObject values=j.getJSONObject("values");Iterator<String> keys=values.keys();while(keys.hasNext()){String key=keys.next(),value=values.getString(key);if((key.equals("defaultAccount")||key.equals("defaultCategory"))&&!value.isEmpty())value=reference(value,candidates);out.append(key).append(": ").append(value).append('\n');}}String[][] legacy={{"account","Account","അക്കൗണ്ട്"},{"dest","Destination","ലക്ഷ്യ അക്കൗണ്ട്"},{"category","Category","വിഭാഗം"},{"person","Person","ആൾ"}};for(String[] field:legacy)if(j.has(field[0])&&!j.optString(field[0]).isEmpty())out.append(a.t(field[1],field[2])).append(": ").append(j.getString(field[0])).append('\n');String[][] refs={{"accountId","Account","അക്കൗണ്ട്"},{"destId","Destination","ലക്ഷ്യ അക്കൗണ്ട്"},{"categoryId","Category","വിഭാഗം"},{"personId","Person","ആൾ"},{"loan","Linked debt","ബന്ധിപ്പിച്ച കടം"}};for(String[] ref:refs)if(j.has(ref[0])&&!j.optString(ref[0]).isEmpty())out.append(a.t(ref[1],ref[2])).append(": ").append(reference(j.getString(ref[0]),candidates)).append('\n');return out.toString().trim();}
 void reviewRepayments(RepaymentReviewStore.Review review)throws Exception{LinearLayout content=a.dialogBody();JSONObject loan=new JSONObject(review.records.get(review.issue.loanId).payload);String currency=loan.optString("currency","INR");content.addView(a.text(a.t("Different devices recorded repayments that exceed the original debt when combined. Hisab has not merged or chosen which payment is mistaken. Check your records before removing anything.","വ്യത്യസ്ത ഉപകരണങ്ങളിലെ തിരിച്ചടവുകൾ കൂട്ടുമ്പോൾ മൂല കടത്തേക്കാൾ കൂടുതലാണ്. Hisab ഇത് ലയിപ്പിച്ചിട്ടില്ല; തെറ്റായ തിരിച്ചടവ് തിരഞ്ഞെടുത്തിട്ടില്ല. എന്തെങ്കിലും നീക്കുന്നതിന് മുമ്പ് നിങ്ങളുടെ രേഖകൾ പരിശോധിക്കുക."),14,a.MUTED,false));a.gap(content,12);content.addView(a.text(a.t("Original principal: ","മൂല കടം: ")+Ledger.number(review.issue.principal)+" "+currency+"\n"+a.t("Combined repayments: ","ആകെ തിരിച്ചടവ്: ")+Ledger.number(review.issue.total)+" "+currency,18,a.FG,true));Map<String,List<SyncModel.Record>> candidates=new TreeMap<>();for(SyncModel.Record r:review.records.values())candidates.put(r.id,Collections.singletonList(r));a.gap(content,10);content.addView(a.text(describe(review.records.get(review.issue.loanId),candidates),13,a.MUTED,false));for(String id:review.issue.repayments){SyncModel.Record payment=review.records.get(id);a.gap(content,18);content.addView(a.text(describe(payment,candidates),14,a.FG,false));a.gap(content,6);content.addView(a.button(a.t("Remove this repayment","ഈ തിരിച്ചടവ് നീക്കുക"),()->confirmPaymentRemoval(review,id),false));}ScrollView scroll=new ScrollView(a);scroll.addView(content);a.dialog().setTitle(a.t("Review repayments","തിരിച്ചടവുകൾ പരിശോധിക്കുക")).setView(scroll).setNegativeButton(a.t("Keep offline for now","ഇപ്പോൾ ഫോണിൽ സൂക്ഷിക്കുക"),null).show();}
 private void confirmPaymentRemoval(RepaymentReviewStore.Review review,String payment){act(()->{JSONObject record=new JSONObject(review.records.get(payment).payload);a.dialog().setTitle(a.t("Remove this repayment?","ഈ തിരിച്ചടവ് നീക്കണോ?")) .setMessage(Ledger.number(record.getLong("amount"))+" "+record.optString("currency","INR")+" · "+record.getString("day")+"\n"+record.optString("note")+"\n\n"+a.t("Removes this exact repayment, not the original debt. Account balances and the amount still owed will reflect its removal after the whole ledger passes validation. All choices stay staged until then. Sync sends the deletion to your Drive and other devices. This cannot be undone; adding a payment again creates a new record.","ഈ തിരിച്ചടവ് മാത്രം നീക്കും; മൂല കടം നീക്കില്ല. എല്ലാ കണക്കുകളും പരിശോധിച്ച ശേഷം അക്കൗണ്ട് ബാലൻസിലും ബാക്കി കടത്തിലും ഈ മാറ്റം പ്രതിഫലിക്കും. അതുവരെ തിരഞ്ഞെടുപ്പുകൾ പരിശോധനയ്ക്കായി മാത്രം സൂക്ഷിക്കും. സമന്വയത്തിൽ ഇത് നിങ്ങളുടെ Drive-ലേക്കും മറ്റു ഉപകരണങ്ങളിലേക്കും അയയ്ക്കും. തിരിച്ചെടുക്കാനാവില്ല; വീണ്ടും ചേർത്താൽ പുതിയ കണക്കാകും.")) .setNegativeButton(a.t("Cancel","വേണ്ട"),null).setPositiveButton(a.t("Remove this repayment","ഈ തിരിച്ചടവ് നീക്കുക"),(d,n)->act(()->{controller.removeReviewedRepayment(review.key,review.revision,payment);a.dismissLedgerDialogs();a.page="cloud";a.render();})).show();});}
 private void confirmVersion(ConflictReviewStore.Review review,int selected){a.dialog().setTitle(a.t("Keep this version?","ഈ പകർപ്പ് സൂക്ഷിക്കണോ?")) .setMessage(a.t("Version ","പകർപ്പ് ")+(selected+1)+"\n\n"+a.t("Other versions of this record will be superseded after the full ledger passes validation. Other conflicting records still need your review. Sync will send your final choices to your own Drive.","എല്ലാ കണക്കുകളും പരിശോധിച്ച ശേഷം ഇതേ കണക്കിന്റെ മറ്റു പകർപ്പുകൾക്ക് പകരം ഇത് ഉപയോഗിക്കും. മറ്റു വ്യത്യാസങ്ങളും പരിശോധിക്കണം. അവസാന തിരഞ്ഞെടുപ്പുകൾ സമന്വയത്തിൽ നിങ്ങളുടെ Drive-ലേക്ക് അയയ്ക്കും.")) .setNegativeButton(a.t("Cancel","വേണ്ട"),null).setPositiveButton(a.t("Keep this version","ഇത് സൂക്ഷിക്കുക"),(d,n)->act(()->{controller.resolveConflict(review.key,review.revision,selected,false);a.toast(a.t("Choice saved. Review any remaining conflicts before syncing.","തിരഞ്ഞെടുപ്പ് സൂക്ഷിച്ചു. സമന്വയത്തിന് മുമ്പ് ബാക്കിയുള്ള വ്യത്യാസങ്ങളും പരിശോധിക്കുക."));a.page="cloud";a.render();})).show();}
 void about(){a.dialog().setTitle("Hisab").setMessage(a.t("by AiCoN\n0.2.2-dev · private development build.\n\nManual entry. Optional Google Drive app-data sync. No bank connection, ads, analytics, notification or SMS reading, bulk contact access or AiCoN account server. SMS and WhatsApp reminders always open a reviewed composer. You must tap Send in your messaging app; carrier fees may apply to SMS. Hisab has no automatic SMS sender or SMS permission. Bundled font licences are available in Appearance > Font. Only contacts you explicitly pick are read; saved contact links and profile photos stay on this device, outside Drive and backups. Local-only records never upload automatically. Cloud resets keep small content-free markers to protect deleted records. Saved backups and CSV exports are separate. This build still needs real-device and Google Drive testing.\n\nOriginal code, design and icons. Not financial advice.","by AiCoN\nസ്വകാര്യ വികസന പതിപ്പ്.\n\nനിങ്ങൾ ചേർക്കുന്ന കണക്കുകൾ മാത്രം. Google Drive ബന്ധം നിർബന്ധമല്ല. ബാങ്ക് ബന്ധമോ പരസ്യമോ ട്രാക്കിങ്ങോ ഇല്ല. നോട്ടിഫിക്കേഷനോ SMS-ഓ വായിക്കില്ല. നിങ്ങൾ തിരഞ്ഞെടുക്കുന്ന കോൺടാക്ട് മാത്രം വായിക്കും; കോൺടാക്ട് ബന്ധവും പ്രൊഫൈൽ ഫോട്ടോയും ഫോണിൽ മാത്രം, Drive-ലോ ബാക്കപ്പിലോ ഇല്ല. AiCoN അക്കൗണ്ട് സെർവർ ഇല്ല. ഫോണിലെ വേറിട്ട കണക്കുകൾ തനിയെ അയയ്ക്കില്ല. ക്ലൗഡിൽ നീക്കിയ കണക്കുകൾ സംരക്ഷിക്കാൻ വിവരങ്ങളില്ലാത്ത ചെറിയ അടയാളങ്ങൾ സൂക്ഷിക്കും. ബാക്കപ്പും CSVയും വേറെയാണ്. യഥാർത്ഥ ഉപകരണത്തിലും Google Drive-ലും പരിശോധന ബാക്കിയുണ്ട്.\n\nസ്വന്തം കോഡും രൂപവും ഐക്കണുകളും. സാമ്പത്തിക ഉപദേശമല്ല.")) .setPositiveButton(a.t("Done","കഴിഞ്ഞു"),null).setNeutralButton(a.t("Source code","സോഴ്സ് കോഡ്"),(d,n)->a.startActivity(new Intent(Intent.ACTION_VIEW,android.net.Uri.parse("https://github.com/aicon-hub/hisab")))).setNegativeButton("AiCoN",(d,n)->a.startActivity(new Intent(Intent.ACTION_VIEW,android.net.Uri.parse("https://aicon-hub.github.io/")))).show();}
